<?php
/** PostgreSQL persistence boundary; original WordPress/domain modules stay unchanged. */
class HSE_PG_DB extends HSE_DB {
 private $pg;
 function __construct($config){
  $this->prefix=$config['prefix']??'st_';if(!preg_match('/^[a-zA-Z][a-zA-Z0-9_]{0,30}$/D',$this->prefix))throw new RuntimeException('Invalid database prefix');
  if(!extension_loaded('pgsql'))throw new RuntimeException('PHP pgsql extension unavailable');
  $values=['host'=>$config['host'],'port'=>(int)($config['port']??5432),'dbname'=>$config['name'],'user'=>$config['user'],'password'=>$config['password'],'sslmode'=>$config['sslmode']??'verify-full','channel_binding'=>$config['channel_binding']??'prefer','connect_timeout'=>'10'];
  if(!empty($config['sslrootcert']))$values['sslrootcert']=$config['sslrootcert'];
  $parts=[];foreach($values as $key=>$value)$parts[]=$key."='".str_replace(['\\',"'"],['\\\\',"\\'"],(string)$value)."'";
  $this->pg=@pg_connect(implode(' ',$parts),PGSQL_CONNECT_FORCE_NEW);if(!$this->pg)throw new RuntimeException('External PostgreSQL connection unavailable');
 }
 function get_charset_collate(){return '';}
 function prepare($sql,...$args){if(count($args)===1&&is_array($args[0]))$args=$args[0];$i=0;return preg_replace_callback('/%[sdf]/',function($m)use(&$i,$args){if(!array_key_exists($i,$args))throw new RuntimeException('Invalid SQL arguments');$v=$args[$i++];return $m[0]==='%d'?(string)(int)$v:($m[0]==='%f'?(string)(float)$v:pg_escape_literal($this->pg,(string)$v));},$sql);}
 function query($sql){
  if(preg_match('/^INSERT IGNORE INTO /i',$sql))$sql=preg_replace('/^INSERT IGNORE INTO /i','INSERT INTO ',$sql).' ON CONFLICT DO NOTHING';
  $sql=preg_replace('/ ON DUPLICATE KEY UPDATE value=VALUES\(value\)$/',' ON CONFLICT (name) DO UPDATE SET value=EXCLUDED.value',$sql);
  $r=@pg_query($this->pg,$sql);$this->last_error=$r===false?'PostgreSQL query failed':'';
  if($r===false)return false;
  return pg_num_fields($r)>0?$r:pg_affected_rows($r);
 }
 function get_results($sql,$format=ARRAY_A){$r=$this->query($sql);if($r===false||is_int($r))throw new RuntimeException('Database query failed');$rows=pg_fetch_all($r);foreach($rows as &$row){if(isset($row['content']))$row['content']=pg_unescape_bytea($row['content']);}unset($row);return $rows;}
 function get_row($sql,$format=ARRAY_A){return $this->get_results($sql,$format)[0]??null;}
 function get_var($sql){$row=$this->get_row($sql);return $row?array_values($row)[0]:null;}
 private function identifier($name){if(!preg_match('/^[a-zA-Z][a-zA-Z0-9_]*$/D',$name))throw new RuntimeException('Invalid database identifier');return strtolower($name);}
 private function parameters($sql,$values){$r=@pg_query_params($this->pg,$sql,$values);$this->last_error=$r===false?'PostgreSQL query failed':'';return $r===false?false:pg_affected_rows($r);}
 function insert($table,$row,$formats=null){$keys=array_map([$this,'identifier'],array_keys($row));$values=[];$params=[];foreach($row as $key=>$value){$values[]=$key==='content'?'\\x'.bin2hex($value):$value;$params[]='$'.count($values);}return $this->parameters('INSERT INTO '.$this->identifier($table).' ('.implode(',',$keys).') VALUES ('.implode(',',$params).')',$values);}
 function update($table,$row,$where,$formats=null,$whereFormats=null){$sets=[];$conditions=[];$values=[];foreach($row as $key=>$value){$values[]=$value;$sets[]=$this->identifier($key).'=$'.count($values);}foreach($where as $key=>$value){$values[]=$value;$conditions[]=$this->identifier($key).'=$'.count($values);}return $this->parameters('UPDATE '.$this->identifier($table).' SET '.implode(',',$sets).' WHERE '.implode(' AND ',$conditions),$values);}
 function migrate($sql){
  if(!preg_match('/^CREATE TABLE IF NOT EXISTS ([a-zA-Z0-9_]+)/',$sql,$m))throw new RuntimeException('Unsupported schema');
  $table=$m[1];$root=$this->prefix.'hse_';
  // Explicit equivalent schema, not general SQL rewriting. Bytea preserves private binary assets.
  $schemas=[
   'records'=>"id varchar(36) PRIMARY KEY,kind varchar(32) NOT NULL,site_id varchar(36) NOT NULL DEFAULT '',company_id varchar(36) NOT NULL DEFAULT '',version bigint NOT NULL DEFAULT 1,author_id bigint NOT NULL,created_at timestamp NOT NULL,updated_at timestamp NOT NULL,payload text NOT NULL",
   'revisions'=>'id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,record_id varchar(36) NOT NULL,version bigint NOT NULL,payload text NOT NULL,created_at timestamp NOT NULL,author_id bigint NOT NULL,UNIQUE(record_id,version)',
   'requests'=>'request_key varchar(64) PRIMARY KEY,fingerprint varchar(64) NOT NULL,response text NOT NULL',
   'assets'=>"id varchar(36) PRIMARY KEY,site_id varchar(36) NOT NULL,company_id varchar(36) NOT NULL DEFAULT '',author_id bigint NOT NULL,name varchar(200) NOT NULL,mime varchar(80) NOT NULL,digest varchar(64) NOT NULL,content bytea NOT NULL,created_at timestamp NOT NULL"
  ];
  $suffix=substr($table,strlen($root));if(strpos($table,$root)!==0||!isset($schemas[$suffix]))throw new RuntimeException('Unsupported table');
  // One transaction-scoped lock serializes concurrent schema initialization, including poolers.
  if($this->query('BEGIN')===false)throw new RuntimeException('Schema transaction unavailable');
  try{
   $this->get_var($this->prepare('SELECT pg_advisory_xact_lock(hashtextextended(%s,0))',$root.'schema'));
   if($this->query('CREATE TABLE IF NOT EXISTS '.$table.' ('.$schemas[$suffix].')')===false)throw new RuntimeException('Schema unavailable');
   if(in_array($suffix,['records','assets'])&&$this->query('CREATE INDEX IF NOT EXISTS '.$table.'_scope ON '.$table.' (site_id'.($suffix==='records'?',kind':'').')')===false)throw new RuntimeException('Index unavailable');
   if($this->query('COMMIT')===false)throw new RuntimeException('Schema commit failed');
  }catch(Throwable $e){$this->query('ROLLBACK');throw $e;}
 }
}
